fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        if maxsplit == 0 {
            // No splitting performed
            result.push(vec![s]);
            continue;
        }
        
        if s.is_empty() {
            // Empty string results in a single empty string
            result.push(vec![String::new()]);
            continue;
        }
        
        let mut parts = Vec::new();
        let mut remaining = s.as_str();
        let mut splits_remaining = maxsplit as usize;
        
        // Perform right split by searching from the right
        while splits_remaining > 0 {
            if let Some(pos) = remaining.rfind(&sep) {
                // Split at the found separator
                let (right_part, left_part) = remaining.split_at(pos + sep.len());
                let right_without_sep = &right_part[..right_part.len() - sep.len()];
                
                parts.push(right_without_sep.to_string());
                remaining = left_part;
                splits_remaining -= 1;
            } else {
                // No more separators found
                break;
            }
        }
        
        // Add the remaining left part
        parts.push(remaining.to_string());
        
        // Reverse to get correct order (since we collected from right to left)
        parts.reverse();
        result.push(parts);
    }
    
    result
}